import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HEADER */}
      <div className="about-hero">
        <h1>
          About <span>Me</span>
        </h1>

        <p className="tagline">
          IT Developer focused on building intelligent, user-first digital systems.
        </p>
      </div>

      {/* MAIN CONTENT */}
      <div className="about-wrapper">

        {/* LEFT SIDE */}
        <div className="about-left">

          <div className="content-block">
            <h2>My Profile</h2>
            <p>
              I am an Information Technology student passionate about building
              real-world software solutions that are practical, scalable, and efficient.
              I enjoy understanding how systems work at a deeper level and translating
              ideas into clean, structured applications.
            </p>

            <p>
              My approach is centered on logical thinking — breaking complex problems
              into smaller components and solving them step by step through consistent
              learning and hands-on development.
            </p>
          </div>

        </div>

        {/* RIGHT SIDE */}
        <div className="about-right">

          <div className="card">
            <h3>🎓 Education</h3>

            <p className="bold">B.Tech – Information Technology</p>
            <p className="muted">Panimalar Engineering College</p>

            <div className="row">
              <span className="badge">2023 – 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>

            <p className="desc">
              Focused on software development, system design, and building real-world projects.
            </p>
          </div>

          <div className="card">
            <h3>💡 Interests</h3>

            <ul>
              <li>Full Stack Development</li>
              <li>Java & Backend Systems</li>
              <li>UI/UX Design</li>
              <li>Data Analytics</li>
              <li>Artificial Intelligence</li>
            </ul>
          </div>

        </div>

      </div>

      {/* STATS */}
      <div className="stats">
        <div className="stat">
          <h3>5+</h3>
          <p>Projects</p>
        </div>

        <div className="stat">
          <h3>10+</h3>
          <p>Technologies</p>
        </div>

        <div className="stat">
          <h3>2+</h3>
          <p>Domains</p>
        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0f172a, #050816);
          color: white;
        }

        /* HEADER */
        .about-hero h1 {
          font-size: 44px;
          margin-bottom: 6px;
        }

        .about-hero span {
          color: #38BDF8;
        }

        .tagline {
          color: #94a3b8;
          margin-bottom: 40px;
        }

        /* LAYOUT */
        .about-wrapper {
          display: grid;
          grid-template-columns: 1.4fr 1fr;
          gap: 40px;
          align-items: start;
        }

        /* LEFT */
        .content-block h2 {
          color: #38BDF8;
          margin-bottom: 12px;
        }

        .content-block p {
          color: #cbd5e1;
          line-height: 1.8;
          margin-bottom: 12px;
        }

        /* RIGHT */
        .about-right {
          display: flex;
          flex-direction: column;
          gap: 18px;
        }

        .card {
          padding: 20px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
          transition: 0.3s ease;
        }

        .card:hover {
          transform: translateY(-4px);
          box-shadow: 0 10px 25px rgba(56,189,248,0.15);
        }

        h3 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        .bold {
          font-weight: 600;
        }

        .muted {
          color: #94a3b8;
        }

        .desc {
          margin-top: 10px;
          color: #cbd5e1;
          font-size: 14px;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 8px;
        }

        .badge {
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
          padding: 3px 8px;
          border-radius: 8px;
          font-size: 11px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        ul {
          padding-left: 18px;
          color: #cbd5e1;
        }

        ul li {
          margin-bottom: 6px;
        }

        /* STATS */
        .stats {
          display: flex;
          justify-content: space-between;
          margin-top: 50px;
          text-align: center;
        }

        .stat h3 {
          color: #38BDF8;
          font-size: 28px;
        }

        .stat p {
          color: #94a3b8;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .about-wrapper {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
            gap: 20px;
          }
        }

      `}</style>

    </div>
  );
}
